const input = $input.first().json;

// DEBUG: Let's find where the actual text lives
let textToScan = '';
let source = 'unknown';

// Check every possible location the text could be
if (input.body && typeof input.body === 'object' && input.body.text) {
  // Webhook sends: { headers: {...}, body: { text: "..." } }
  textToScan = input.body.text;
  source = input.body.source || 'unknown';

} else if (input.body && typeof input.body === 'string') {
  // Body is a string — try to parse it
  try {
    const parsed = JSON.parse(input.body);
    textToScan = parsed.text || input.body;
    source = parsed.source || 'unknown';
  } catch(e) {
    textToScan = input.body;
  }

} else if (input.text) {
  // Direct: { text: "..." }
  textToScan = input.text;
  source = input.source || 'unknown';

} else if (input.data && typeof input.data === 'string') {
  textToScan = input.data;
  source = input.source || 'unknown';

} else {
  // LAST RESORT: stringify but EXCLUDE headers/params/query
  // Only stringify the body
  const bodyOnly = input.body || input;
  textToScan = typeof bodyOnly === 'string' ? bodyOnly : JSON.stringify(bodyOnly);
  source = 'fallback';
}

const metadata = {
  timestamp: new Date().toISOString(),
  inputLength: textToScan.length,
  scanId: 'SCAN-' + Date.now() + '-' + Math.random().toString(36).substr(2, 6),
  source: source
};

return [{
  json: {
    originalText: textToScan,
    metadata: metadata
  }
}];

const data = $input.first().json;
