    riskEmoji: data.riskEmoji,
    recommendedAction: data.riskAction,
    algorithmUsed: 'Composite Privacy Risk Score v2.0',
    academicBasis: [
      'NIST SP 800-122 (PII Classification)',
      'Sweeney 2000 (Mosaic Effect / Re-identification)',
      'Microsoft Presidio (Context-boosted Detection)',
      'FAIR Framework (Risk Quantification)',
      'ISO 27701 (Privacy Information Management)'
    ]
  },

  // ─── SCORE BREAKDOWN (transparency) ───
  scoreBreakdown: data.scoreBreakdown,

  // ─── DETECTION SUMMARY ───
  detection: {
    totalPiiFound: data.totalFindings,
    findingsByTier: { tier1: 0, tier2: 0, tier3: 0 },
    findingsBySeverity: { LOW: 0, MEDIUM: 0, HIGH: 0, CRITICAL: 0 },
    findingsByCategory: {},
    findingsByDetector: { regex: 0, ai_llm: 0, both: 0 }
  },

  // ─── MASKING SUMMARY ───
