    strategiesUsed: {}
  },

  // ─── CONTEXTUAL RISKS (from AI) ───
  contextualRisks: data.contextualRisks || [],

  // ─── DETAILED FINDINGS (sanitized — no raw PII in logs!) ───
  detailedFindings: (data.findings || []).map(f => ({
    type: f.type,
    tier: f.tier,
    severity: f.severity,
    category: f.category,
    detectedBy: f.detectedBy,
    confidence: f.confidence,
    adjustedScore: f.adjustedScore,
    maskingStrategy: f.maskingStrategy,
    dualDetection: f.dualDetection || false,
    // NEVER log the actual PII value — only a safe preview
    valuePreview: (f.value || '').substring(0, 2) + '***',
    valueLength: (f.value || '').length
  })),

  // ─── COMPLIANCE FLAGS ───
  complianceFlags: {
    gdprRelevant: data.totalFindings > 0,
    hipaaRelevant: (data.findings || []).some(f => f.category === 'health'),
    pciRelevant: (data.findings || []).some(f => f.category === 'financial'),
    ccpaRelevant: data.totalFindings > 0,
    identityTheftRisk: data.scoreBreakdown?.identityTheftKit?.detected || false
  }
};

// Populate counts
(data.findings || []).forEach(f => {
  // By tier
  const tierKey = 'tier' + (f.tier || 2);
  auditReport.detection.findingsByTier[tierKey] = 
    (auditReport.detection.findingsByTier[tierKey] || 0) + 1;

  // By severity
  if (auditReport.detection.findingsBySeverity[f.severity] !== undefined) {
    auditReport.detection.findingsBySeverity[f.severity]++;
  }

  // By category
  const cat = f.category || 'unknown';
  auditReport.detection.findingsByCategory[cat] = 
    (auditReport.detection.findingsByCategory[cat] || 0) + 1;

  // By detector
  if (f.detectedBy === 'both_regex_and_ai') {
    auditReport.detection.findingsByDetector.both++;
  } else if (f.detectedBy === 'ai_llm') {
    auditReport.detection.findingsByDetector.ai_llm++;
  } else {
    auditReport.detection.findingsByDetector.regex++;
  }

  // Masking strategies
  const strat = f.maskingStrategy || 'unknown';
  auditReport.masking.strategiesUsed[strat] = 
    (auditReport.masking.strategiesUsed[strat] || 0) + 1;
});

return [{
  json: {
    maskedText: data.maskedText,
    auditReport: auditReport,
    tokenMap: data.tokenMap || {},
    riskLevel: data.riskLevel,
    cprsScore: data.cprsScore,
    riskEmoji: data.riskEmoji
  }
}];

const data = $input.first().json;

return [{
  json: {
    success: true,

    // ─── Core Result ───
    scanId: data.auditReport.reportId,
    riskLevel: data.riskLevel,
    riskEmoji: data.riskEmoji,
