    message: data.cprsScore >= 70 
      ? `🚨 CRITICAL: ${data.auditReport.detection.totalPiiFound} PII items detected. CPRS Score: ${data.cprsScore}/100. Identity theft risk: ${data.auditReport.complianceFlags.identityTheftRisk ? 'YES' : 'NO'}. All items masked.`
      : data.cprsScore >= 40
      ? `🔴 HIGH RISK: ${data.auditReport.detection.totalPiiFound} PII items detected. CPRS Score: ${data.cprsScore}/100. Items masked.`
      : `⚠️ ${data.auditReport.detection.totalPiiFound} PII items detected and masked. CPRS Score: ${data.cprsScore}/100.`,

    // ─── Full Audit (optional — remove for production) ───
    auditReport: data.auditReport,

